text:
{
 "opening": "This release focuses on expanding locale coverage and correcting localization details for existing languages. It introduces new support for Kazakh and enhances time granularity handling in Russian, while ensuring consistent behavior across Slavic and Nordic locales.",
 "requirements": [
  {
   "id": "m01",
   "text": "The `RussianLocale` must correctly pluralize the word 'second' according to Russian grammar rules based on the numeric value."
  },
  {
   "id": "m02",
   "text": "The `IndonesianLocale` must support humanizing timeframes for 'Qeeks' (quarters) and 'Quarters' using appropriate Indonesian terminology."
  },
  {
   "id": "m03",
   "text": "The `RussianLocale` must provide correct humanization for timeframes with quarter granularity, such as 'a quarter ago' or 'in a quarter'."
  },
  {
   "id": "m05",
   "text": "The `ChineseCNLocale` must format timeframe strings consistently with other Chinese locale implementations, ensuring uniform structure and terminology."
  },
  {
   "id": "m06",
   "text": "The library must expose `KazakhLocale` for full date and time humanization in Kazakh, and ensure `UrduLocale` remains available and functional."
  },
  {
   "id": "m08",
   "text": "The `Arrow` class and base `Locale` interface must support the `dehumanize` method for all Slavic locales, allowing conversion of humanized strings back to datetime objects."
  },
  {
   "id": "m09",
   "text": "The `CzechLocale` and `SlovakLocale` must implement the `dehumanize` method to accurately parse humanized time strings into corresponding datetime instances."
  },
  {
   "id": "m14",
   "text": "The `NewNorwegianLocale` and `NorwegianLocale` must append a period after the day number in ordinal formats, and `PortugueseLocale` ordinals must remain unaffected by these changes."
  }
 ],
 "closing": "Please verify that all public names are exported correctly and that locale-specific tests pass before merging."
}
